# Simulate how a venv's pyvenv.cfg changes sys.prefix and sys.path.
CFG = """home = /usr/bin
include-system-site-packages = false
version = 3.12.3
"""

def parse_cfg(text):
    out = {}
    for line in text.splitlines():
        if "=" in line:
            k, v = line.split("=", 1)
            out[k.strip()] = v.strip()
    return out

def startup(interpreter_dir, cfg):
    # site.py looks for pyvenv.cfg next to (or one level above) the interpreter
    base = "/usr"
    if cfg is None:
        return {"prefix": base, "base_prefix": base,
                "path": [base + "/lib/python3.12/site-packages"]}
    venv = interpreter_dir.rsplit("/bin", 1)[0]
    path = [venv + "/lib/python3.12/site-packages"]
    if cfg["include-system-site-packages"] == "true":
        path.append(base + "/lib/python3.12/site-packages")
    return {"prefix": venv, "base_prefix": base, "path": path}

for name, d, cfg in [("global", "/usr/bin", None),
                     ("venv", "/proj/.venv/bin", parse_cfg(CFG))]:
    s = startup(d, cfg)
    in_venv = s["prefix"] != s["base_prefix"]   # the standard test
    print(name, "| prefix:", s["prefix"], "| in_venv:", in_venv)
    print("   path:", s["path"])

# Find out which "requests" an import would pick: first match on sys.path wins.
# Simulated file system: directory -> names it contains.
FS = {
    "/proj":                    ["app.py", "requests.py"],   # local file shadows!
    "/venv/lib/site-packages":  ["requests", "urllib3"],
    "/usr/lib/python3":         ["os.py"],
}

def find(name, path):
    for d in path:
        for entry in FS.get(d, []):
            if entry == name or entry == name + ".py":
                return d + "/" + entry
    return None

path = ["/proj", "/venv/lib/site-packages", "/usr/lib/python3"]
print("sys.path:", path)
print("import requests ->", find("requests", path))

FS["/proj"].remove("requests.py")          # fix: rename the local file
print("after rename   ->", find("requests", path))

wrong = ["/usr/lib/python3"]               # pip installed into another interpreter
print("other python   ->", find("requests", wrong))

# Library requirements are loose ranges; an application lock pins the whole tree.
INDEX = {
    "web":   {"2.1": ["http>=1", "log>=2"], "2.0": ["http>=1"]},
    "http":  {"1.4": ["log>=2"], "1.3": []},
    "log":   {"2.5": [], "2.4": []},
}

def newest(pkg):
    return max(INDEX[pkg], key=lambda v: tuple(map(int, v.split("."))))

def lock(requirements):
    pinned, queue = {}, list(requirements)
    while queue:
        req = queue.pop(0)
        name = req.split(">=")[0]
        if name in pinned:
            continue
        pinned[name] = newest(name)
        queue += INDEX[name][pinned[name]]
    return pinned

library_requirements = ["web>=2.0"]            # abstract, what a library declares
print("declared:", library_requirements)
print("lock file (pins everything):", lock(library_requirements))

# Dependency confusion: highest version across all indexes wins unless pinned.
PUBLIC   = {"acme-internal": "99.0.0", "requests": "2.32.3"}   # attacker uploaded 99.0.0
PRIVATE  = {"acme-internal": "1.4.0"}

def v(s):
    return tuple(int(x) for x in s.split("."))

def install_any_index(name):
    options = [(v(i[name]), src, i[name]) for src, i in
               (("public", PUBLIC), ("private", PRIVATE)) if name in i]
    return max(options)[1:]                       # newest version wins

def install_pinned(name, pins):
    index = {"public": PUBLIC, "private": PRIVATE}[pins.get(name, "public")]
    return pins.get(name, "public"), index[name]

print("extra-index style:", install_any_index("acme-internal"))
print("pinned index     :", install_pinned("acme-internal", {"acme-internal": "private"}))
print("requests         :", install_pinned("requests", {"acme-internal": "private"}))
